class Product { constructor(public name: string, public price: number) {}
}

class ProductBuilder {
  private name = '';
  private price = 0;
  setName(n: string) { this.name = n; return this; }
  setPrice(p: number) { this.price = p; return this; }
  build() { return new Product(this.name, this.price); }
}

const p = new ProductBuilder().setName('S').setPrice(10).build();

